#!/usr/bin/env python3
"""Generate the billing unit and DeepSeek face-value prices from root parameters."""
import json
import re
from decimal import Decimal
from pathlib import Path

root = Path(__file__).resolve().parents[1]
config = json.loads((root / "billing-credits.json").read_text(), parse_float=Decimal)
lines = [
    "// Code generated by tools/generate_billing_credits.py; DO NOT EDIT.",
    "package service", "", "const (",
    f'\tBillingCreditUnit = {json.dumps(config["unit"])}',
]
for tier in ("flash", "pro"):
    for key, suffix in (("input", "InputPrice"), ("output", "OutputPrice"), ("cache_read", "CacheRead")):
        value = Decimal(config["deepseek"][f"{tier}_per_million"][key]) / 1_000_000
        lines.append(f"\tdeepseek{tier.title()}{suffix} = {value}")
lines.extend([")", "", "var officialCreditPrices = map[string]ModelPricing{"])
fields = {
    "input": "InputPricePerToken",
    "output": "OutputPricePerToken",
    "cache_read": "CacheReadPricePerToken",
    "image_input": "ImageInputPricePerToken",
}
for model, card in config["models"].items():
    lines.append(f'\t{json.dumps(model)}: {{')
    for key, value in card["per_million"].items():
        lines.append(f'\t\t{fields[key]}: {Decimal(value) / 1_000_000},')
    lines.append("\t},")
lines.extend(["}", "", "var officialCreditPricePrefixes = map[string]string{"])
for model, card in config["models"].items():
    for prefix in card.get("prefixes", []):
        lines.append(f'\t{json.dumps(prefix)}: {json.dumps(model)},')
lines.extend(["}", ""])
(root / "backend/internal/service/billing_credits_defaults_gotocc.go").write_text("\n".join(lines))

# The distributed catalog carries the same current face-value cards. Historical
# DeepSeek Pro timing remains in BillingService; current Pro calls use Flash.
target = root / "backend/resources/model-pricing/model_prices_and_context_window.json"
source = target.read_text()
catalog = json.loads(source)
catalog_fields = {
    "input": "input_cost_per_token",
    "output": "output_cost_per_token",
    "cache_read": "cache_read_input_token_cost",
    "image_input": "input_cost_per_image_token",
}
cards = {name: card["per_million"] for name, card in config["models"].items()}
for name in catalog:
    if name.startswith("deepseek-"):
        cards[name] = config["deepseek"]["flash_per_million"]
for name, rates in cards.items():
    entry = dict(catalog.get(name, {}))
    if name in config["models"]:
        entry.update(config["models"][name]["catalog"])
    entry.update({catalog_fields[key]: float(Decimal(value) / 1_000_000) for key, value in rates.items()})
    entry.update({"source_currency": "CNY", "billing_unit": config["unit"], "prefer_bundled_pricing": True})
    rendered = json.dumps(entry, ensure_ascii=False, indent=2).replace("\n", "\n  ")
    match = re.search(r"^  " + re.escape(json.dumps(name)) + r":\s*", source, re.MULTILINE)
    if match:
        _, length = json.JSONDecoder().raw_decode(source[match.end():])
        source = source[:match.end()] + rendered + source[match.end() + length:]
    else:
        source = source.rstrip()[:-1].rstrip() + ",\n  " + json.dumps(name) + ": " + rendered + "\n}\n"
target.write_text(source)
